#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M, C;
    if (!(cin >> N >> M >> C)) return 0;

    vector<int> next_song(M + 1, 0);

    for (int i = 1; i <= N; ++i) {
        int a, d;
        cin >> a >> d;
        if (next_song[d] == 0) {
            next_song[d] = a;
        }
    }

    vector<int> visited(M + 1, 0);
    int current = C;
    int swaps = 0;

    while (current != 0 && next_song[current] != 0) {
        if (visited[current]) {
            cout << -1 << "\n";
            return 0;
        }
        visited[current] = 1;
        current = next_song[current];
        swaps++;
    }

    cout << swaps << "\n";

    return 0;
}
